// src/image/image.ts
import {
  union
} from "@prosekit/core";

// src/image/image-commands.ts
import {
  defineCommands,
  insertNode
} from "@prosekit/core";
function defineImageCommands() {
  return defineCommands({
    insertImage: (attrs) => {
      return insertNode({ type: "image", attrs });
    }
  });
}

// src/image/image-spec.ts
import {
  defineNodeSpec
} from "@prosekit/core";
function defineImageSpec() {
  return defineNodeSpec({
    name: "image",
    attrs: {
      src: { default: null },
      width: { default: null },
      height: { default: null }
    },
    group: "block",
    defining: true,
    draggable: true,
    parseDOM: [
      {
        tag: "img[src]",
        getAttrs: (element) => {
          if (typeof element === "string") {
            return { src: null };
          }
          const src = element.getAttribute("src") || null;
          let width = null;
          let height = null;
          const rect = element.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            width = rect.width;
            height = rect.height;
          } else if (element instanceof HTMLImageElement && element.naturalWidth > 0 && element.naturalHeight > 0) {
            width = element.naturalWidth;
            height = element.naturalHeight;
          }
          return { src, width, height };
        }
      }
    ],
    toDOM(node) {
      const attrs = node.attrs;
      return ["img", attrs];
    }
  });
}

// src/image/image.ts
function defineImage() {
  return union(defineImageSpec(), defineImageCommands());
}
export {
  defineImage,
  defineImageCommands,
  defineImageSpec
};
